use serde_json::{Value, Number};

pub fn solve(input: Value) -> Value {
    let mut map: std::collections::HashMap<Number, Number> = std::collections::HashMap::new();

    for row in input.as_array().unwrap() {
        let key = row[0].as_i64().unwrap();
        let value = row[1].as_i64().unwrap();
        *map.entry(Number::from(key)).or_insert(Number::from(0)) += Number::from(value);
    }

    let mut entries: Vec<(Number, Number)> = map.into_iter().collect();
    entries.sort_by(|a, b| a.0.cmp(&b.0));

    serde_json::to_value(entries).unwrap()
}
